import sys


def main():
    data = sys.stdin.read().split()
    n, m, s = int(data[0]), int(data[1]), int(data[2])
    edges = []
    for i in range(m):
        u = int(data[3 + 3 * i])
        v = int(data[4 + 3 * i])
        w = int(data[5 + 3 * i])
        edges.append((u, v, w))
    dist = [None] * (n + 1)
    dist[s] = 0
    for _ in range(n):
        changed = False
        for u, v, w in edges:
            if dist[u] is None:
                continue
            if dist[v] is None or dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                changed = True
        if not changed:
            break
    for i in range(1, n + 1):
        print(dist[i] if dist[i] is not None else -1)


main()
